import Foundation
#if canImport(CryptoKit)
import CryptoKit
#endif

/// t1268: texts the phone's Secure Enclave key signs that the SERVER also builds. One format per text, here only; the gateway side is
/// in one place too (signin.mjs signinKeyDigest, everyday-limits.mjs everydayText). Cross-test: T1268PhoneTextsCrossTests reads a
/// fixture generated by gateway scripts/t1268-phone-texts-fixture.mjs.
enum PhoneSignHash {
  static func sha256(_ text: String) -> [UInt8] {
    #if canImport(CryptoKit)
    return [UInt8](SHA256.hash(data: Data(text.utf8)))
    #else
    return []
    #endif
  }
}

/// Sign in with Coinbase: proof that this phone holds the key it sent to /signin/start (else no read grant / no one-page setup).
public enum SigninKeyProof {
  public static func text(id: String) -> String { "Kipurse sign-in key v1\nid:\(id)" }
  public static func digest(id: String) -> [UInt8] { PhoneSignHash.sha256(text(id: id)) }
  /// The sign-in id: exactly 32 lowercase hex characters (the server's own format).
  public static func validId(_ s: String) -> Bool { s.count == 32 && s.allSatisfy { "0123456789abcdef".contains($0) } }
  /// A fresh id the app picks itself (16 random bytes).
  public static func newId() -> String {
    var g = SystemRandomNumberGenerator()
    return (0..<16).map { _ in String(format: "%02x", UInt8.random(in: 0...255, using: &g)) }.joined()
  }
  /// The server's prove.digest must be the one the phone computes itself (the phone never signs a digest it did not build).
  public static func serverDigestMatches(_ hex: String?, id: String) -> Bool {
    guard validId(id), let h = hex?.lowercased() else { return false }
    return h == Hex.encode(digest(id: id)).lowercased()
  }
}

/// Everyday (AI) limits: the phone key signs exactly the three amounts it shows (atomic USDC), the wallet and the server's nonce.
public enum EverydaySign {
  public static func text(wallet: String, single: Int64, daily: Int64, term: Int64, nonce: String) -> String {
    "Kipurse everyday limits v1\nwallet:\(wallet.lowercased())\nsingle:\(single)\ndaily:\(daily)\nterm:\(term)\nnonce:\(nonce)"
  }
  public static func digest(wallet: String, single: Int64, daily: Int64, term: Int64, nonce: String) -> [UInt8] {
    PhoneSignHash.sha256(text(wallet: wallet, single: single, daily: daily, term: term, nonce: nonce))
  }
  /// Amounts the phone will sign: positive and single <= daily <= term (the server refuses anything else anyway).
  public static func signable(single: Int64, daily: Int64, term: Int64) -> Bool { single > 0 && daily > 0 && term > 0 && single <= daily && daily <= term }
}
